create function public.create_school(p jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare s uuid;begin if private.role()<>'owner' then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.schools(code,name,timezone)values(lower(p->>'code'),p->>'name',coalesce(p->>'timezone','Asia/Kolkata'))returning id into s;insert into public.subscriptions(school_id,plan,starts_at,ends_at,teacher_limit,student_limit,ai_limit,storage_limit)values(s,p->>'plan',(p->>'startsAt')::timestamptz,(p->>'endsAt')::timestamptz,(p->>'teacherLimit')::int,(p->>'studentLimit')::int,(p->>'aiLimit')::int,coalesce((p->>'storageLimit')::bigint,1073741824));perform private.audit(s,'school.created',s);return s;end$$;
create function public.update_subscription(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare s uuid:=(p->>'schoolId')::uuid;begin if private.role()<>'owner' or length(coalesce(p->>'reason',''))=0 then raise exception 'FORBIDDEN' using errcode='42501';end if;update public.subscriptions set plan=p->>'plan',starts_at=(p->>'startsAt')::timestamptz,ends_at=(p->>'endsAt')::timestamptz,teacher_limit=(p->>'teacherLimit')::int,student_limit=(p->>'studentLimit')::int,ai_limit=(p->>'aiLimit')::int where school_id=s;perform private.audit(s,'subscription.changed',s,p->>'reason');end$$;
create function public.set_school_status(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare s uuid:=(p->>'schoolId')::uuid;begin if private.role()<>'owner' or length(coalesce(p->>'reason',''))=0 then raise exception 'FORBIDDEN' using errcode='42501';end if;update public.schools set status=p->>'status'where id=s;if p->>'status'='suspended' then update private.sessions set revoked_at=now()where user_id in(select id from public.memberships where school_id=s);end if;perform private.audit(s,'school.status',s,p->>'reason');end$$;
create function public.enroll_student(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();begin perform private.require_access(s,true);if not private.assigned((p->>'classId')::uuid) or private.role() not in ('teacher','administrator')then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.enrollments values(s,(p->>'classId')::uuid,(p->>'studentId')::uuid,p->>'roll',true)on conflict(class_id,student_id)do update set roll=excluded.roll,active=true;perform private.audit(s,'student.enrolled',(p->>'studentId')::uuid);end$$;
create function public.deactivate_user(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare m public.memberships;begin select * into m from public.memberships where id=(p->>'userId')::uuid for update;if m.school_id<>private.school()or not(private.role()='administrator' and m.role in ('teacher','student')or private.role()='teacher' and m.role='student' and private.student_access(m.id))or length(coalesce(p->>'reason',''))=0 then raise exception 'FORBIDDEN' using errcode='42501';end if;update public.memberships set active=false,credential_version=credential_version+1 where id=m.id;update private.sessions set revoked_at=now()where user_id=m.id;update public.teacher_profiles set visible=false,revision=revision+1 where teacher_id=m.id;perform private.audit(m.school_id,'account.deactivated',m.id,p->>'reason');end$$;
create function public.force_logout(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare m public.memberships;begin select * into m from public.memberships where id=(p->>'userId')::uuid;if length(coalesce(p->>'reason',''))=0 or not(m.school_id=private.school()and(private.role()='administrator' and m.role in ('teacher','student')or private.role()='teacher' and m.role='student' and private.student_access(m.id)))then raise exception 'FORBIDDEN' using errcode='42501';end if;update private.sessions set revoked_at=now()where user_id=m.id;perform private.audit(m.school_id,'account.force_logout',m.id,p->>'reason');end$$;
create function public.takeover_attempt(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid for update;perform private.require_access(a.school_id);if private.role()<>'student' or a.student_id<>auth.uid()or a.status<>'in_progress'or now()>=a.deadline then raise exception 'FORBIDDEN' using errcode='42501';end if;-- API requires password reauthentication before invoking this RPC; direct invocation cannot bypass it.
raise exception 'RECENT_REAUTH_REQUIRED' using errcode='42501';end$$;
create function public.record_integrity(p jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare a public.attempts;i uuid;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid;perform private.require_access(a.school_id);if a.student_id<>auth.uid() or private.role()<>'student' then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.integrity_events(school_id,attempt_id,student_id,type,client_at)values(a.school_id,a.id,auth.uid(),p->>'type',(p->>'clientAt')::timestamptz)returning id into i;return i;end$$;
create function public.review_integrity(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare a public.attempts;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid;if not(private.exam_teacher(a.version_id) and p->>'outcome' in ('cleared','warning','invalidated')or a.student_id=auth.uid()and private.role()='student' and p->>'outcome'='appeal' or private.role()='administrator'and a.school_id=private.school()and p->>'outcome'in('cleared','warning','invalidated'))or length(coalesce(p->>'reason',''))=0 then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.integrity_reviews(school_id,attempt_id,actor_id,outcome,reason)values(a.school_id,a.id,auth.uid(),p->>'outcome',p->>'reason');insert into public.notifications(school_id,recipient_id,event_key,type,resource_id)values(a.school_id,a.student_id,'review:'||gen_random_uuid(),'integrity.review',a.id);perform private.audit(a.school_id,'integrity.reviewed',a.id,p->>'reason');end$$;
create function public.mark_notification(p jsonb)returns void language plpgsql security definer set search_path='' as $$begin update public.notifications set read_at=coalesce(read_at,now())where id=(p->>'id')::uuid and recipient_id=auth.uid() and school_id=private.school();end$$;
create function public.save_question_draft(p jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();i uuid;begin perform private.require_access(s,true);if private.role()<>'teacher' then raise exception 'FORBIDDEN' using errcode='42501';end if;if p->>'id' is null then insert into public.question_drafts(school_id,author_id,raw_text,content)values(s,auth.uid(),p->>'rawText',p->'content')returning id into i;else update public.question_drafts set raw_text=p->>'rawText',content=p->'content',revision=revision+1 where id=(p->>'id')::uuid and author_id=auth.uid()and revision=(p->>'revision')::int returning id into i;if not found then raise exception 'STALE_REVISION';end if;end if;return i;end$$;
create function public.cancel_exam(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare e public.exam_versions;begin select * into e from public.exam_versions where id=(p->>'versionId')::uuid for update;if not private.exam_teacher(e.id)or exists(select 1 from public.attempts where version_id=e.id)then raise exception 'EXAM_STARTED_OR_FORBIDDEN';end if;update public.exam_versions set status='cancelled'where id=e.id;perform private.audit(e.school_id,'exam.cancelled',e.id,p->>'reason');end$$;
revoke execute on function public.create_school(jsonb),public.update_subscription(jsonb),public.set_school_status(jsonb),public.enroll_student(jsonb),public.deactivate_user(jsonb),public.force_logout(jsonb),public.takeover_attempt(jsonb),public.record_integrity(jsonb),public.review_integrity(jsonb),public.mark_notification(jsonb),public.save_question_draft(jsonb),public.cancel_exam(jsonb)from public,anon,authenticated;
grant execute on function public.create_school(jsonb),public.update_subscription(jsonb),public.set_school_status(jsonb),public.enroll_student(jsonb),public.deactivate_user(jsonb),public.force_logout(jsonb),public.takeover_attempt(jsonb),public.record_integrity(jsonb),public.review_integrity(jsonb),public.mark_notification(jsonb),public.save_question_draft(jsonb),public.cancel_exam(jsonb)to authenticated;
